exports.tokenBucketTrace = function(capacity, initial, refill, costs) {
  // Validate inputs
  if (capacity < 0) {
    return null;
  }
  if (initial < 0) {
    return null;
  }
  if (refill < 0) {
    return null;
  }
  if (costs && costs.length === 0) {
    return null;
  }
  if (costs && costs.some(c => c < 0)) {
    return null;
  }
  if (costs && costs.some(c => c > capacity)) {
    return null;
  }
  if (initial > capacity) {
    return null;
  }

  const tokens = initial;
  const history = [];

  // Helper to check affordability
  const canAfford = (cost) => {
    return tokens >= cost;
  };

  // Helper to emit result
  const emit = (result) => {
    history.push(result);
  };

  // Helper to refill
  const refill = () => {
    tokens = Math.min(capacity, tokens + refill);
  };

  // Helper to spend
  const spend = (cost) => {
    if (!canAfford(cost)) {
      emit(-1);
      return false; // Rejection
    }
    tokens -= cost;
    emit(tokens);
    return true; // Success
  };

  // Process each cost
  for (let i = 0; i < costs.length; i++) {
    const cost = costs[i];
    if (i === 0) {
      // First request: no refill, just spend
      if (canAfford(cost)) {
        tokens -= cost;
        emit(tokens);
      } else {
        emit(-1);
      }
    } else {
      // Subsequent requests: refill first, then spend
      refill();
      if (canAfford(cost)) {
        tokens -= cost;
        emit(tokens);
      } else {
        emit(-1);
      }
    }
  }

  return history;
};

